// Eighteen real situations people find themselves in today. Each has places
// to be, four roles to fill (people are generated fresh every run), shared
// stakes, things you can do, things that can go wrong, and a clock.

import type { Scenario } from './types.ts'

const pad = (n: number) => String(n).padStart(2, '0')
/** Day N, hh:00 — beats of `step` hours starting at `start` o'clock. */
const days = (start: number, step: number) => (b: number) => {
  const h = start + b * step
  return `Day ${Math.floor(h / 24) + 1} · ${pad(h % 24)}:00`
}
const minutes = (start: number, step: number) => (b: number) => {
  const m = start + b * step
  return `${pad(Math.floor(m / 60) % 24)}:${pad(m % 60)}`
}
const weeks = (b: number) => `Week ${Math.floor(b / 3) + 1} · ${['Mon', 'Wed', 'Fri'][b % 3]}`

